import json
from typing import Any, Dict
async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    request_ids = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            offer_id = str(inner.get('offer_id') or inner.get('offerId') or '')
            rid = inner.get('requestIds')
            if isinstance(rid, (list, tuple)):
                request_ids = ','.join(str(x) for x in rid)
            elif rid is not None:
                request_ids = str(rid)
    except Exception:
        offer_id = ''
    ret: Output = {
        "record_json": record_json,
        "offer_id": offer_id,
        "requestIds": request_ids
    }
    return ret

import json
import urllib.request
from typing import Any, Dict

SQL_URL = 'http://10.86.13.201:31281/api/v1/appstore/audit/sql-query'
SQL_ID_RESULT = '20260626002'

def _first_row(resp):
    if not isinstance(resp, dict):
        return {}
    rows = resp.get('execute_sql_resp') or resp.get('executeSqlResp') or []
    if isinstance(rows, list) and rows and isinstance(rows[0], dict):
        return rows[0]
    if isinstance(rows, dict):
        return rows
    return resp

async def main(args):
    request_ids = str(args.params.get('requestIds') or '')
    body = json.dumps({'sqlId': SQL_ID_RESULT,
                       'params': 'requestIds:' + request_ids}).encode('utf-8')
    req = urllib.request.Request(SQL_URL, data=body, method='POST',
                                 headers={'Content-Type': 'application/json'})
    try:
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception as e:
        ret: Output = {'pass': '', 'error_list': '', 'audit_summary': '',
                       'resultCode': 'E', 'fail_reason': '稽核结果查询失败：' + repr(e)}
        return ret
    row = _first_row(resp)
    raw_pass = row.get('pass')
    if raw_pass in (None, ''):
        if row.get('error_list'):
            raw_pass = '0'
        elif str(row.get('isAllFinished', '')).lower() in ('y', 'yes', 'true', '1'):
            raw_pass = '1'
        else:
            raw_pass = ''
    err = row.get('error_list')
    if isinstance(err, (list, dict)):
        err = json.dumps(err, ensure_ascii=False)
    summary = row.get('audit_summary') or row.get('auditConclusion') or ''
    ret: Output = {'pass': str(raw_pass),
                   'error_list': ('' if err is None else str(err)),
                   'audit_summary': str(summary),
                   'resultCode': str(resp.get('resultCode', '0'))}
    return ret

import json
from typing import Any, Dict

_PASSTHROUGH = ('pass', 'error_list', 'audit_summary', 'risk_list', 'compare_list',
                'requestIds', 'sales_id', 'file_id', 'globalId', 'testScenes', 'offer_id')

def _any(v):
    # 平台出参可能是已序列化 JSON 字符串，也可能是原始 list/str；统一尝试解析
    if isinstance(v, (list, dict)):
        return v
    if v is None:
        return None
    s = str(v)
    if not s.strip():
        return None
    t = s.strip()
    if t[0] in '[{' and t[-1] in ']}':
        try:
            return json.loads(t)
        except Exception:
            return s
    return s

async def main(args):
    p = args.params
    env: Dict[str, Any] = {}
    for key in _PASSTHROUGH:
        if key in p and p.get(key) is not None and str(p.get(key)) != '':
            env[key] = _any(p.get(key))
    md = str(p.get('md') or p.get('markdown') or '')
    md_key = str(p.get('md_key') or 'report_md')
    if md:
        env[md_key] = md
        # 兼容占位：老消费方仅认 raw 时可回退取值
        env.setdefault('raw', md)
    ret: Output = {
        'record_json': json.dumps(env, ensure_ascii=False)
    }
    return ret

